final class FifoLot { const FifoLot({required this.id,required this.globalId,required this.available,required this.unitCostCents}); final int id; final String globalId; final int available; final int unitCostCents; }
final class FifoAllocation { const FifoAllocation(this.lot,this.quantity); final FifoLot lot; final int quantity; int get totalCostCents=>quantity*lot.unitCostCents; }
List<FifoAllocation> allocateFifo(List<FifoLot> lots,int quantity){if(quantity<=0)throw ArgumentError.value(quantity,'quantity');var remaining=quantity;final result=<FifoAllocation>[];for(final lot in lots){if(remaining==0)break;if(lot.available<=0)continue;final take=remaining<lot.available?remaining:lot.available;result.add(FifoAllocation(lot,take));remaining-=take;}if(remaining>0)throw StateError('Stock insuficiente.');return result;}
